INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李克用王处存合攻镇州拔天长镇", "start_year": 892, "end_year": 892, "time_original": "892年三月癸丑", "dynasty": "唐", "description": "李克用与王处存合兵攻王镕，攻取天长镇。", "phases": [], "location_name": "天长镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e3f59615-4ac2-590c-aed9-95bbd9a3949c"}, {"title": "王镕新市大败河东定州军", "start_year": 892, "end_year": 892, "time_original": "892年三月戊午", "dynasty": "唐", "description": "王镕与李克用王处存联军在新市交战，大败对手，书载杀获三万余。", "phases": [], "location_name": "新市", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1c5d311f-35e3-5257-8873-51f3b91e13fd"}, {"title": "李克用退屯栾城，朝廷诏和四镇", "start_year": 892, "end_year": 892, "time_original": "892年三月辛酉及其后", "dynasty": "唐", "description": "李克用退屯栾城，朝廷下诏和解河东、镇、定、幽四镇。", "phases": [], "location_name": "栾城、河东、镇州、定州、幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c3d9a640-8d5f-57c6-9ae8-6b8d8b086baf"}, {"title": "杨晟求诸杨攻东川解彭州围", "start_year": 892, "end_year": 892, "time_original": "892年三月条；具体日未载", "dynasty": "唐", "description": "杨晟给杨守贞、杨守忠、杨守厚写信，要求攻击东川以解彭州围，杨守贞等同意。", "phases": [], "location_name": "彭州、东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "acb3999b-19ab-53d7-b146-6532e5bad41b"}, {"title": "窦行实内应败露，被顾彦晖斩", "start_year": 892, "end_year": 892, "time_original": "892年三月条；杨守厚至涪城时", "dynasty": "唐", "description": "神策督将窦行实戍梓州，被杨守厚暗诱为内应。杨守厚至涪城时事泄，顾彦晖斩窦行实，杨守厚逃去。", "phases": [], "location_name": "梓州、涪城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bccd5565-42ad-57d5-b926-e538b61bf951"}, {"title": "吉谏袭败杨守厚", "start_year": 892, "end_year": 892, "time_original": "892年三月条；内应事泄后", "dynasty": "唐", "description": "杨守贞杨守忠军到后无归处，在绵、剑间停留。王建遣吉谏袭杨守厚并击败之。", "phases": [], "location_name": "绵州、剑州一带", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9d525e9b-f896-5bd4-aa61-0e110432a8a8"}, {"title": "李简钟阳邀击杨守忠", "start_year": 892, "end_year": 892, "time_original": "892年三月癸亥", "dynasty": "唐", "description": "西川将李简在钟阳邀击杨守忠，书载斩获三千余。", "phases": [], "location_name": "钟阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "edd89e86-62cd-59f9-8750-6524d6a1c489"}, {"title": "李简铜鉾破杨守厚，降众万五千", "start_year": 892, "end_year": 892, "time_original": "892年夏四月", "dynasty": "唐", "description": "李简再次在铜鉾击败杨守厚，书载斩获三千余、降一万五千人；杨守忠与杨守厚皆逃走。", "phases": [], "location_name": "铜鉾", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3ae2d844-d74e-5a28-98fc-e1f451ed75a7"}, {"title": "杭州置武胜军，钱镠任防御使", "start_year": 892, "end_year": 892, "time_original": "892年四月乙酉", "dynasty": "唐", "description": "朝廷在杭州设置武胜军，任钱镠为防御使。", "phases": [], "location_name": "杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ac533214-4b01-5468-a0ee-e574c5deb4cd"}, {"title": "贾德晟怨李顺节死，西门君遂奏杀", "start_year": 892, "end_year": 892, "time_original": "892年四月条；具体日未载", "dynasty": "唐", "description": "天威军使贾德晟因李顺节之死心怀怨愤，西门君遂厌恶，上奏后杀之。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d3013abb-e778-5a06-9012-253e3967eab2"}, {"title": "贾德晟部骑千余奔凤翔", "start_year": 892, "end_year": 892, "time_original": "892年四月条；贾德晟被杀后", "dynasty": "唐", "description": "贾德晟部下千余骑奔凤翔，李茂贞势力因此增强。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4b134014-f098-5488-8526-2a368942f3fe"}, {"title": "李匡威侵云代，李克用引军还", "start_year": 892, "end_year": 892, "time_original": "892年四月壬寅", "dynasty": "唐", "description": "李匡威出兵侵云、代，壬寅李克用开始率军返回。", "phases": [], "location_name": "云州、代州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "95e03f3c-a174-59ea-ac65-7eac423ae548"}, {"title": "张训李德诚寿河败徐兵取楚州", "start_year": 892, "end_year": 892, "time_original": "892年四月条；具体日未载", "dynasty": "唐", "description": "时溥遣兵南侵至楚州，张训李德诚在寿河击败之，取得楚州，拘执刺史刘瓚。", "phases": [], "location_name": "寿河、楚州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "72a7b0d7-505a-53c1-91a0-481bf4c28fab"}, {"title": "王行瑜加兼中书令", "start_year": 892, "end_year": 892, "time_original": "892年五月", "dynasty": "唐", "description": "朝廷加邠宁节度使王行瑜兼中书令。", "phases": [], "location_name": "邠宁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "93e51b6a-fbb9-5e04-87fe-63fa21964293"}, {"title": "杨行密破孙儒广德营，张训断粮道", "start_year": 892, "end_year": 892, "time_original": "892年六月戊寅战前；具体日未载", "dynasty": "唐", "description": "杨行密屡败孙儒军，攻破广德营；张训驻安吉，切断孙儒粮道。", "phases": [], "location_name": "广德、安吉", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0060fcf0-1667-56c0-a5de-cdcfd75d16d2"}, {"title": "孙儒军粮尽染疫，遣刘建锋马殷掠县", "start_year": 892, "end_year": 892, "time_original": "892年六月戊寅战前；具体日未载", "dynasty": "唐", "description": "孙儒粮尽，士卒大疫，遣刘建锋与马殷分兵掠诸县。", "phases": [], "location_name": "宣州一带诸县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "501810d5-b1c6-5ee7-a91f-a77fb931edcc"}, {"title": "杨行密趁孙儒疾疟出击，雨中大败敌军", "start_year": 892, "end_year": 892, "time_original": "892年六月戊寅", "dynasty": "唐", "description": "杨行密听说孙儒患疟，纵兵进攻，恰逢大雨天暗，孙儒军大败。", "phases": [], "location_name": "宣州战场", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4ad79fd8-b922-5adb-8bc3-b5cc385cec1e"}, {"title": "安仁义破五十余寨，田頵擒斩孙儒", "start_year": 892, "end_year": 892, "time_original": "892年六月戊寅条；战败后", "dynasty": "唐", "description": "安仁义攻破孙儒五十余寨，田頵在阵中擒孙儒并斩之，将首级送京师；孙儒部众多降杨行密。", "phases": [], "location_name": "宣州战场、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4fb3fe8b-949d-534b-b98c-1f9d596b882c"}, {"title": "刘建锋马殷收七千余众南走洪州", "start_year": 892, "end_year": 892, "time_original": "892年六月孙儒死后", "dynasty": "唐", "description": "刘建锋马殷收余众七千，南走洪州，推刘建锋为帅、马殷为先锋指挥使，张佶为谋主。", "phases": [], "location_name": "洪州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9fd05a2b-7f6f-5497-8773-12e326d0127b"}, {"title": "刘建锋军到江西时增至十余万的后续", "start_year": null, "end_year": null, "time_original": "比至江西；具体年月未载", "dynasty": "唐", "description": "《通鉴》续述刘建锋马殷所领军到江西时增至十余万。", "phases": [], "location_name": "江西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f11429c8-4b2f-599f-b41c-ee0bcfa07b96"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

